</head>
<body>
    <div class='slide-in-blurred-top'>
        "
    & IF (
        NOT ( ISBLANK ( [Rolling12MonthNetSalesValue] ) ),
        "<p><span class='category-name R12-NetSales'>R12 Net Sales: </span><span class='value' id='current'>"
            & FORMAT ( [Rolling12MonthNetSalesValue], "$#,##0.00" ) & "</span></p>",
        ""
    )
    & IF (
        NOT ( ISBLANK ( [PreviousYearRollingNetSalesValue] ) ),
        "<p><span class='category-name PY-NetSales'>PY R12 Net Sales: </span><span class='value' id='previous'>"
            & FORMAT ( [PreviousYearRollingNetSalesValue], "$#,##0.00" ) & "</span></p>",
        ""
    )
    & IF (
        NOT ( ISBLANK ( [PercentChangeNetSalesValue] ) ),
        "<p><span class='category-name percent-change'>% Change: </span><span class='value' id='current'>"
            & FORMAT ( [PercentChangeNetSalesValue], "#,0.00%" )
            & IF (
                [PercentChangeNetSalesValue] > 0,
                "<span class='arrow up-arrow'>&#9650;</span>",
                /* Green up arrow */
                "<span class='arrow down-arrow'>&#9660;</span>" /* Red down arrow */
            ) & "</span></p>",
        ""
    ) & "
    </div>
</body>
</html>"

